// Metadata-only alert — never forward payment refs, tokens, PII, or DB/service-role keys.
const src = items[0].json || {};
const exec = src.execution || {};
const wf = src.workflow || {};
const name = String(wf.name || src.workflowName || 'unknown-workflow').slice(0, 80);
const status = String(exec.status || src.status || 'error').slice(0, 40);
const lastNode = String(exec.lastNodeExecuted || src.lastNodeExecuted || 'n/a').slice(0, 60);
const when = new Date().toISOString();
const message = [
  'Vergeo5 workflow failure',
  `workflow: ${name}`,
  `status: ${status}`,
  `lastNode: ${lastNode}`,
  `at: ${when}`,
].join('\n');
return [{ json: { message, workflowName: name, status, lastNode, at: when } }];

// Deduplicate repeated failure pages within a cooldown window (shared alert route).
// State lives in workflow-scoped n8n static data — no external store, metadata only.
// A workflow that errors on every tick pages the founder once per window, not per run.
const store = $getWorkflowStaticData('global');
const windowMin = Number($env.ALERT_DEDUPE_WINDOW_MINUTES || 15);
const ttlMs = Math.max(1, windowMin) * 60 * 1000;
const now = Date.now();
const sent = (store.failureAlertsSent && typeof store.failureAlertsSent === 'object') ? store.failureAlertsSent : {};
// prune expired keys so the map cannot grow unbounded
for (const k of Object.keys(sent)) { if (now - Number(sent[k] || 0) > ttlMs) delete sent[k]; }
const src = ($input.first() && $input.first().json) || {};
const key = [src.workflowName || 'unknown', src.status || 'error', src.lastNode || 'n/a'].join('|');
const last = Number(sent[key] || 0);
const suppress = last > 0 && (now - last) < ttlMs;
if (!suppress) sent[key] = now;
store.failureAlertsSent = sent;
return [{ json: { ...src, dedupe_key: key, suppress, dedupe_window_minutes: windowMin } }];
